create or replace function public.manage_school_timetable_entry(p_school_id uuid,p_payload jsonb,p_entry_id uuid default null) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$
declare v_id uuid;v_class uuid;v_year uuid;v_subject uuid;v_teacher uuid;v_day smallint;v_start time;v_end time;v_room text;v_period uuid;v_double boolean;v_period_number smallint;v_double_allowed boolean;
begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 if not private.has_school_role(p_school_id,array['owner','school_admin','headteacher']::text[]) then raise exception 'Only school leadership can manage the timetable';end if;
 v_class:=(p_payload->>'class_id')::uuid;v_year:=(p_payload->>'academic_year_id')::uuid;v_subject:=(p_payload->>'subject_id')::uuid;v_teacher:=nullif(p_payload->>'teacher_membership_id','')::uuid;v_day:=(p_payload->>'weekday')::smallint;v_room:=nullif(trim(p_payload->>'room'),'');v_period:=nullif(p_payload->>'period_id','')::uuid;v_double:=coalesce((p_payload->>'is_double_period')::boolean,false);
 if v_period is not null then
  select p.period_number,p.start_time,p.end_time,p.is_double_allowed into v_period_number,v_start,v_end,v_double_allowed from public.school_timetable_periods p where p.id=v_period and p.school_id=p_school_id and p.academic_year_id=v_year and p.period_type='lesson';
  if not found then raise exception 'Choose a configured lesson period for this academic year';end if;
  if v_double and not v_double_allowed then raise exception 'This period does not allow double lessons';end if;
  if v_double then if not exists(select 1 from public.school_timetable_periods p where p.school_id=p_school_id and p.academic_year_id=v_year and p.period_number=v_period_number+1 and p.period_type='lesson' and p.is_double_allowed) then raise exception 'A double period must use two consecutive lesson periods without a break';end if;select p.end_time into v_end from public.school_timetable_periods p where p.school_id=p_school_id and p.academic_year_id=v_year and p.period_number=v_period_number+1 and p.period_type='lesson';end if;
 else v_start:=(p_payload->>'start_time')::time;v_end:=(p_payload->>'end_time')::time;v_double:=false;end if;
 if v_day not between 1 and 5 or v_start>=v_end then raise exception 'Choose a weekday and a valid lesson time';end if;
 if not exists(select 1 from public.classes c where c.school_id=p_school_id and c.id=v_class and c.academic_year_id=v_year and c.is_active) then raise exception 'Class does not belong to the selected academic year';end if;
 if not exists(select 1 from public.class_subjects cs where cs.school_id=p_school_id and cs.class_id=v_class and cs.subject_id=v_subject and (v_teacher is null or cs.teacher_membership_id=v_teacher)) then raise exception 'Subject or teacher is not assigned to this class';end if;
 if v_teacher is not null and not exists(select 1 from public.school_memberships sm where sm.school_id=p_school_id and sm.id=v_teacher and sm.is_active and sm.role in ('teacher','class_teacher')) then raise exception 'Teacher membership is inactive or invalid';end if;
 if exists(select 1 from public.school_timetable_entries t where t.school_id=p_school_id and t.weekday=v_day and t.academic_year_id=v_year and t.id is distinct from p_entry_id and t.start_time<v_end and t.end_time>v_start and (t.class_id=v_class or (v_teacher is not null and t.teacher_membership_id=v_teacher) or (v_room is not null and lower(trim(coalesce(t.room,'')))=lower(trim(v_room))))) then raise exception 'Timetable conflict: class, teacher or room is already booked during this time';end if;
 if p_entry_id is null then insert into public.school_timetable_entries(school_id,class_id,academic_year_id,subject_id,teacher_membership_id,weekday,start_time,end_time,room,period_id,is_double_period) values(p_school_id,v_class,v_year,v_subject,v_teacher,v_day,v_start,v_end,v_room,v_period,v_double) returning id into v_id;else update public.school_timetable_entries set class_id=v_class,academic_year_id=v_year,subject_id=v_subject,teacher_membership_id=v_teacher,weekday=v_day,start_time=v_start,end_time=v_end,room=v_room,period_id=v_period,is_double_period=v_double,updated_at=now() where school_id=p_school_id and id=p_entry_id returning id into v_id;if v_id is null then raise exception 'Timetable lesson not found';end if;end if;
 update public.school_timetable_publications set is_published=false,updated_at=now() where school_id=p_school_id and academic_year_id=v_year and class_id=v_class and is_published;return v_id;
end $$;
create or replace function public.publish_school_timetable(p_school_id uuid,p_academic_year_id uuid,p_class_id uuid,p_publish boolean default true) returns integer language plpgsql security definer set search_path=public,private,pg_temp as $$
declare v_id uuid;v_version integer;v_count integer;v_user uuid;v_class_name text;
begin
 v_user:=auth.uid();if v_user is null then raise exception 'Authentication required';end if;
 if not private.has_school_role(p_school_id,array['owner','school_admin','headteacher']::text[]) then raise exception 'Only school leadership can publish timetables';end if;
 select c.name into v_class_name from public.classes c where c.id=p_class_id and c.school_id=p_school_id and c.academic_year_id=p_academic_year_id;if not found then raise exception 'Class does not belong to this academic year';end if;
 select count(*) into v_count from public.school_timetable_entries e where e.school_id=p_school_id and e.academic_year_id=p_academic_year_id and e.class_id=p_class_id;if p_publish and v_count=0 then raise exception 'Add at least one lesson before publishing';end if;
 insert into public.school_timetable_publications(school_id,academic_year_id,class_id,version,published_by,is_published,published_at,updated_at) values(p_school_id,p_academic_year_id,p_class_id,1,v_user,p_publish,now(),now()) on conflict(school_id,academic_year_id,class_id) do update set version=school_timetable_publications.version+1,published_by=excluded.published_by,is_published=excluded.is_published,published_at=now(),updated_at=now() returning id,version into v_id,v_version;
 if p_publish then
  insert into public.school_timetable_publication_notifications(school_id,academic_year_id,class_id,publication_id,version,message) values(p_school_id,p_academic_year_id,p_class_id,v_id,v_version,'A new or updated class timetable has been published.');
  insert into public.school_announcements(school_id,title,body,priority,audience_type,audience_roles,class_id,status,publish_at,created_by,published_by,created_at,updated_at) values(p_school_id,'Timetable published · '||v_class_name,'The timetable for '||v_class_name||' has been published or updated. Sign in to view the latest class timetable.','normal','roles',array['teacher','class_teacher','parent','student']::text[],null,'published',now(),v_user,v_user,now(),now());
 end if;return v_version;
end $$;
